"use client";

import "./toggle-group.css";
import { ToggleGroup as BaseToggleGroup } from "@base-ui/react/toggle-group";
import type React from "react";
import { cn } from "tailwind-variants";

import { ToggleRoot } from "../toggle";
import { ToggleGroupContext } from "./toggle-group.context";
import { toggleGroupVariants, type ToggleGroupVariants } from "./toggle-group.variants";

export type ToggleGroupProps = ToggleGroupVariants & React.ComponentProps<typeof BaseToggleGroup>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/toggle-group/content.md
 */
export const ToggleGroupRoot = ({
  children,
  className,
  orientation = "horizontal",
  variant = "default",
  ...props
}: ToggleGroupProps) => {
  const slots = toggleGroupVariants({ orientation, variant });

  return (
    <ToggleGroupContext.Provider value={{ slots }}>
      <BaseToggleGroup className={cn(slots.root(), className)} orientation={orientation} {...props}>
        {children}
      </BaseToggleGroup>
    </ToggleGroupContext.Provider>
  );
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/toggle-group/content.md
 */
export const ToggleItem = ToggleRoot;
/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/toggle-group/content.md
 */
export const ToggleGroupItem = ToggleRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const toggleGroupVariants = tv({
  slots: {
    root: "toggle-group",
  },
  variants: {
    orientation: {
      horizontal: {
        root: "flex-row",
      },
      vertical: {
        root: "flex-col",
      },
    },
    variant: {
      default: {
        root: "bg-muted p-1 rounded-lg gap-1",
      },
      outline: {
        root: "border border-input rounded-md p-1 gap-1",
      },
    },
  },
  defaultVariants: {
    orientation: "horizontal",
    variant: "default",
  },
});

export type ToggleGroupVariants = VariantProps<typeof toggleGroupVariants>;

"use client";

import { createContext, useContext } from "react";

import { toggleGroupVariants } from "./toggle-group.variants";

export type ToggleGroupContext = {
  slots: ReturnType<typeof toggleGroupVariants>;
};

export const ToggleGroupContext = createContext<ToggleGroupContext | null>(null);

export const useToggleGroupContext = () => {
  const context = useContext(ToggleGroupContext);
  return context ?? { slots: toggleGroupVariants() };
};

import { ToggleRoot as ToggleGroupItem, ToggleRoot as ToggleItem } from "../toggle";
import { ToggleGroupRoot } from "./toggle-group";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/toggle-group/content.md
 */
export const ToggleGroup = {
  Item: ToggleGroupItem,
  Root: ToggleGroupRoot,
};

export { ToggleGroupItem, ToggleItem, ToggleGroupRoot };

export type { ToggleGroupProps } from "./toggle-group";
export { ToggleGroupContext, useToggleGroupContext } from "./toggle-group.context";
export { type ToggleGroupVariants, toggleGroupVariants } from "./toggle-group.variants";
